require_once __DIR__.'/../includes/auth.php';require_once __DIR__.'/../includes/schema.php';$schema=dental_schema($pdo);$labIdColumn=$schema->labId();$serviceIdColumn=$schema->serviceId();$serviceNameColumn=$schema->serviceName();$id=require_lab();$error='';$success='';if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$d=[];foreach(['nom_laboratoire','nom_gerant','telephone','email','adresse','ville','description'] as $f)$d[$f]=trim((string)($_POST[$f]??''));$services=array_values(array_unique(array_filter(array_map('intval',(array)($_POST['services']??[])),fn($v)=>$v>0)));try{foreach($d as $v)if($v==='')throw new RuntimeException('Tous les champs obligatoires sont requis.');if(!filter_var($d['email'],FILTER_VALIDATE_EMAIL))throw new RuntimeException('Adresse e-mail invalide.');if(!$services)throw new RuntimeException('Choisissez au moins un service.');$q=$pdo->prepare("SELECT `$labIdColumn` FROM laboratoire WHERE email=? AND `$labIdColumn`<>?");$q->execute([$d['email'],$id]);if($q->fetch())throw new RuntimeException('Cet e-mail est déjà utilisé.');$q=$pdo->prepare("SELECT `$serviceIdColumn` FROM service WHERE `$serviceIdColumn`=?");foreach($services as $sid){$q->execute([$sid]);if(!$q->fetch())throw new RuntimeException('Service invalide.');}$pdo->beginTransaction();$q=$pdo->prepare("UPDATE laboratoire SET nom_laboratoire=?,nom_gerant=?,telephone=?,email=?,adresse=?,ville=?,site_web=?,instagram=?,description=? WHERE `$labIdColumn`=?");$q->execute([$d['nom_laboratoire'],$d['nom_gerant'],$d['telephone'],$d['email'],$d['adresse'],$d['ville'],trim($_POST['site_web']??'')?:null,trim($_POST['instagram']??'')?:null,$d['description'],$id]);$pdo->prepare('DELETE FROM laboratoire_service WHERE laboratoire_id=?')->execute([$id]);$q=$pdo->prepare('INSERT INTO laboratoire_service(laboratoire_id,service_id) VALUES(?,?)');foreach($services as $sid)$q->execute([$id,$sid]);$pdo->commit();$_SESSION['nom_laboratoire']=$d['nom_laboratoire'];$success='Profil mis à jour.';}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e instanceof RuntimeException?$e->getMessage():'Mise à jour impossible.';}}
$q=$pdo->prepare("SELECT * FROM laboratoire WHERE `$labIdColumn`=?");$q->execute([$id]);$lab=$q->fetch();$services=$pdo->query("SELECT `$serviceIdColumn` id,`$serviceNameColumn` nom FROM service ORDER BY `$serviceNameColumn`")->fetchAll();$q=$pdo->prepare('SELECT service_id FROM laboratoire_service WHERE laboratoire_id=?');$q->execute([$id]);$selected=array_map('intval',array_column($q->fetchAll(),'service_id'));
?>
<?php $pageTitle='Mon profil — DentalLink'; $assetPrefix='../'; $navContext='laboratoire'; require __DIR__ . '/../includes/header.php'; require __DIR__ . '/../includes/navbar.php'; ?><main><h1>Mon profil</h1><?php if($error):?><p role="alert"><?=e($error)?></p><?php endif;?><?php if($success):?><p><?=e($success)?></p><?php endif;?><form method="post"><?=csrf_field()?><?php foreach(['nom_laboratoire'=>'Nom du laboratoire','nom_gerant'=>'Gérant','telephone'=>'Téléphone','email'=>'E-mail','adresse'=>'Adresse','ville'=>'Ville','site_web'=>'Site web','instagram'=>'Instagram','description'=>'Description'] as $key=>$label):?><label><?=e($label)?><input name="<?=e($key)?>" value="<?=e($lab[$key]??'')?>" <?=in_array($key,['nom_laboratoire','nom_gerant','telephone','email','adresse','ville','description'])?'required':''?>></label><?php endforeach;?><fieldset><legend>Services</legend><?php foreach($services as $s):?><label><input type="checkbox" name="services[]" value="<?=$s['id']?>" <?=in_array((int)$s['id'],$selected,true)?'checked':''?>> <?=e($s['nom'])?></label><?php endforeach;?></fieldset><button>Enregistrer</button></form></main><?php require_once __DIR__ . "/../includes/footer.php"; ?>


